<?php
$baseDir=dirname(__DIR__);
require_once $baseDir.'/services/ManagerRequestContext.php';
ManagerRequestContext::startSession();
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AnyTour — маршрутизация</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f6f8;color:#18202a;font:15px/1.4 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:980px;margin:auto;padding:18px}.head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.card{background:#fff;border-radius:16px;padding:16px;margin-bottom:14px;box-shadow:0 1px 3px #0001}h1,h2{margin:0 0 12px}a{color:#1d4ed8;text-decoration:none}label{display:block;font-size:13px;color:#687281;margin:8px 0 4px}input,select{width:100%;padding:10px;border:1px solid #d8dde3;border-radius:10px;background:#fff;font:inherit}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.checks{display:flex;flex-wrap:wrap;gap:8px}.checks label{margin:0;background:#f3f4f6;padding:7px 9px;border-radius:9px;color:#18202a}.checks input{width:auto}.btn{border:0;border-radius:10px;padding:10px 13px;background:#111827;color:#fff;cursor:pointer;margin-top:12px}.btn:disabled{opacity:.55;cursor:wait}.item{border-top:1px solid #eee;padding:10px 0}.muted{font-size:13px;color:#7b8490}.hidden{display:none}@media(max-width:700px){.grid{grid-template-columns:1fr}.wrap{padding:12px}}
</style></head><body><div class="wrap"><div class="head"><div><h1>Маршрутизация</h1><div class="muted">Источники → группы менеджеров → fallback</div></div><a href="./">← Диалоги</a></div><div id="denied" class="card hidden">Доступно только администратору.</div><div id="app" class="hidden"><div class="card"><label>Проект</label><select id="project"></select></div><div class="card"><h2>Группы менеджеров</h2><div id="groups"></div><h3>Новая / изменить группу</h3><input id="groupId" type="hidden"><div class="grid"><div><label>Код</label><input id="groupKey" placeholder="spb"></div><div><label>Название</label><input id="groupName" placeholder="Санкт-Петербург"></div></div><label>Менеджеры</label><div id="members" class="checks"></div><button id="saveGroup" class="btn">Сохранить группу</button></div><div class="card"><h2>Источники</h2><div id="sources"></div><h3>Новый / изменить источник</h3><input id="sourceId" type="hidden"><div class="grid"><div><label>Код источника</label><input id="sourceKey" placeholder="max:anytour-spb"></div><div><label>Название</label><input id="sourceName" placeholder="MAX AnyTour Санкт-Петербург"></div><div><label>Канал</label><select id="channel"><option value="max">MAX</option><option value="telegram">Telegram</option><option value="website">Сайт</option></select></div><div><label>Основная группа</label><select id="primary"></select></div><div><label>Fallback</label><select id="fallbackMode"><option value="none">Никому больше</option><option value="delayed">Через время другой группе</option><option value="immediate">Сразу другой группе</option></select></div><div><label>Fallback-группа</label><select id="fallbackGroup"></select></div><div><label>Через сколько минут</label><input id="fallbackAfter" type="number" min="0" value="3"></div></div><button id="saveSource" class="btn">Сохранить источник</button></div></div></div><script>
const S={csrf:'',manager:null,projects:[],routing:null};const $=id=>document.getElementById(id);async function api(action,data={}){try{const r=await fetch('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,csrf:S.csrf,...data})});const j=await r.json();return j&&typeof j==='object'?j:{ok:false,error:'invalid_response'}}catch(e){return{ok:false,error:'network_error'}}}
function esc(v){const d=document.createElement('div');d.textContent=v??'';return d.innerHTML}async function boot(){const j=await api('me');if(!j.ok||!j.manager||j.manager.role!=='admin'){$('denied').classList.remove('hidden');return}S.csrf=j.csrf;S.manager=j.manager;S.projects=j.projects||[];$('app').classList.remove('hidden');$('project').innerHTML=S.projects.map(p=>`<option value="${esc(p.project_key)}">${esc(p.display_name)}</option>`).join('');$('project').onchange=load;await load()}
async function load(){const key=$('project').value;if(!key)return;const j=await api('routing_snapshot',{project_key:key});if(!j.ok){alert('Не удалось загрузить маршрутизацию');return}S.routing=j.routing||{groups:[],sources:[],managers:[]};render()}
function render(){const r=S.routing;$('groups').innerHTML=r.groups.map(g=>`<div class="item"><b>${esc(g.display_name)}</b> <span class="muted">${esc(g.group_key)}</span><br><span class="muted">${(g.members||[]).map(m=>esc(m.display_name||m.login)).join(', ')||'без менеджеров'}</span> <a href="#" onclick="editGroup(${g.id});return false">изменить</a></div>`).join('')||'<div class="muted">Групп пока нет</div>';$('members').innerHTML=r.managers.map(m=>`<label><input type="checkbox" value="${m.id}"> ${esc(m.display_name||m.login)}</label>`).join('');const opts='<option value="0">—</option>'+r.groups.map(g=>`<option value="${g.id}">${esc(g.display_name)}</option>`).join('');$('primary').innerHTML=opts;$('fallbackGroup').innerHTML=opts;$('sources').innerHTML=r.sources.map(s=>{const p=r.groups.find(g=>Number(g.id)===Number(s.primary_group_id));const f=r.groups.find(g=>Number(g.id)===Number(s.fallback_group_id));const mode={none:'только своей группе',delayed:`fallback через ${s.fallback_after_minutes} мин`,immediate:'fallback сразу'}[s.fallback_mode]||s.fallback_mode;return`<div class="item"><b>${esc(s.display_name)}</b> <span class="muted">${esc(s.source_key)}</span><br><span class="muted">${esc(p?p.display_name:'общий пул')} · ${esc(mode)}${f?' → '+esc(f.display_name):''}</span> <a href="#" onclick="editSource(${s.id});return false">изменить</a></div>`}).join('')||'<div class="muted">Источников пока нет</div>'}
window.editGroup=id=>{const g=S.routing.groups.find(x=>Number(x.id)===Number(id));if(!g)return;$('groupId').value=g.id;$('groupKey').value=g.group_key;$('groupName').value=g.display_name;document.querySelectorAll('#members input').forEach(x=>x.checked=(g.members||[]).some(m=>Number(m.id)===Number(x.value)))};window.editSource=id=>{const s=S.routing.sources.find(x=>Number(x.id)===Number(id));if(!s)return;$('sourceId').value=s.id;$('sourceKey').value=s.source_key;$('sourceName').value=s.display_name;$('channel').value=s.channel||'max';$('primary').value=s.primary_group_id||0;$('fallbackMode').value=s.fallback_mode||'none';$('fallbackGroup').value=s.fallback_group_id||0;$('fallbackAfter').value=s.fallback_after_minutes||0};
$('saveGroup').onclick=async()=>{const member_ids=[...document.querySelectorAll('#members input:checked')].map(x=>Number(x.value));const j=await api('save_group',{project_key:$('project').value,group_id:Number($('groupId').value||0),group_key:$('groupKey').value,display_name:$('groupName').value,member_ids});if(j.ok){$('groupId').value='';$('groupKey').value='';$('groupName').value='';await load()}else alert('Не удалось сохранить группу')};
$('saveSource').onclick=async()=>{const source_key=$('sourceKey').value.trim(),display_name=$('sourceName').value.trim(),fallback_mode=$('fallbackMode').value,fallback_group_id=Number($('fallbackGroup').value||0);if(!source_key){alert('Укажите код источника.');$('sourceKey').focus();return}if(!display_name){alert('Укажите название источника.');$('sourceName').focus();return}if(fallback_mode!=='none'&&!fallback_group_id){alert('Для fallback выберите fallback-группу.');$('fallbackGroup').focus();return}const btn=$('saveSource');btn.disabled=true;const oldText=btn.textContent;btn.textContent='Сохраняем…';const j=await api('save_source',{project_key:$('project').value,source_id:Number($('sourceId').value||0),source_key,display_name,channel:$('channel').value,primary_group_id:Number($('primary').value||0),fallback_mode,fallback_group_id,fallback_after_minutes:Number($('fallbackAfter').value||0)});btn.disabled=false;btn.textContent=oldText;if(j.ok){$('sourceId').value='';$('sourceKey').value='';$('sourceName').value='';$('primary').value='0';$('fallbackMode').value='none';$('fallbackGroup').value='0';$('fallbackAfter').value='3';await load()}else{const msg=j.error==='network_error'?'Нет связи с сервером. Данные формы сохранены — повторите попытку.':'Не удалось сохранить источник. Проверьте, что код источника уникален и выбран правильный проект/группы. Данные формы сохранены.';alert(msg)}};boot();
</script></body></html>